solution:
type Temperature = {
  celsius: Float64;
  invariant: celsius >= -273.15;
}

fn Temperature.to_fahrenheit(self) -> Float64 {
  return self.celsius * 9.0 / 5.0 + 32.0;
}

fn Temperature.to_kelvin(self) -> Float64 {
  return self.celsius + 273.15;
}

fn main() -> Int {
  let boiling: Temperature = Temperature{ celsius: 100.0 };
  io.println(boiling.to_kelvin());
  return 0;
}
